T("c08", """Given rows of comma-separated values (header row first) and a column name, return the sum of numeric values in
that column (values that are not parseable as numbers are ignored). Return the sum rounded to 2 decimals.""",
"""
def solve(csv_text, col):
    lines = [l for l in csv_text.strip().split('\\n') if l]
    header = [h.strip() for h in lines[0].split(',')]
    idx = header.index(col)
    total = 0.0
    for line in lines[1:]:
        parts = [p.strip() for p in line.split(',')]
        try:
            total += float(parts[idx])
        except ValueError:
            pass
    return round(total, 2)
