T("c11", """Given a list of closed intervals [start, end) with integer endpoints, merge overlapping intervals and return
the total length covered by their union as an integer.""",
"""
def solve(intervals):
    if not intervals:
        return 0
    ivs = sorted(intervals)
    total = 0
    cs, ce = ivs[0]
    for s, e in ivs[1:]:
        if s <= ce:
            ce = max(ce, e)
        else:
            total += ce - cs
            cs, ce = s, e
    total += ce - cs
    return total
