T("c20", """Topological sort: given a DAG as {node: [prerequisites]} (edges point prerequisite -> dependent, i.e. the
listed nodes must come before the key... note: key depends on listed nodes), return a topological order as a list
where every listed node appears before the key that depends on it. If there is a cycle, return None. All nodes that
appear anywhere must be included; nodes not appearing as keys have no prerequisites. Deterministic order: among
available nodes, pick the alphabetically smallest.""",
"""
def solve(graph):
    import heapq
    nodes = set(graph)
    for deps in graph.values():
        nodes.update(deps)
    indeg = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}
    for k, deps in graph.items():
        for d in deps:
            indeg[k] += 1
            dependents[d].append(k)
    avail = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(avail)
    out = []
    while avail:
        n = heapq.heappop(avail)
        out.append(n)
        for m in dependents[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(avail, m)
    if len(out) != len(nodes):
        return None
    return out
""",
