T("c24", """Edit distance with custom operation costs given as a dict with keys 'insert', 'delete', 'replace' (positive
ints). Return the minimum total cost to transform string a into string b.""",
"""
def solve(a, b, costs):
    import functools
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i * costs['delete']
    for j in range(n + 1):
        dp[0][j] = j * costs['insert']
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j] + costs['delete'],
                               dp[i][j-1] + costs['insert'],
                               dp[i-1][j-1] + costs['replace'])
    return dp[m][n]
""",
