T("c26", """Solve a 4x4 Sudoku: given a 4x4 grid (list of 4 lists of 4 ints, 0 for empty) using digits 1-4 with the
standard 2x2 box constraint, return the solved grid as a list of lists of ints. The puzzle has a unique solution.
If unsolvable, return None.""",
"""
def solve(grid):
    def ok(g, r, c, v):
        for j in range(4):
            if g[r][j] == v: return False
        for i in range(4):
            if g[i][c] == v: return False
        br, bc = 2 * (r // 2), 2 * (c // 2)
        for i in range(br, br + 2):
            for j in range(bc, bc + 2):
                if g[i][j] == v: return False
        return True
    g = [row[:] for row in grid]
    def solve_rec():
        for r in range(4):
            for c in range(4):
                if g[r][c] == 0:
                    for v in range(1, 5):
                        if ok(g, r, c, v):
                            g[r][c] = v
                            if solve_rec():
                                return True
                            g[r][c] = 0
                    return False
        return True
    if solve_rec():
        return g
    return None
""",
[([[1,0,0,4],[0,4,1,0],[4,0,2,0],[0,1,0,3]],),
 ([[0,0,0,0],[0,1,4,0],[0,4,1,0],[0,0,0,0]],)])

T("c27", """Convex hull: given a list of (x, y) integer points (no three collinear duplicates issue: at least 3 points,
not all collinear), return the vertices of the convex hull in counter-clockwise order, starting from the
lexicographically smallest point (smallest x, then y). Use the monotone chain algorithm. Exclude collinear points
on hull edges.""",
"""
def solve(points):
    pts = sorted(set(map(tuple, points)))
    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]
""",
[([(0,0),(0,2),(2,0),(2,2),(1,1)],), ([(0,0),(1,1),(2,2),(3,3),(1,0)],)])

T("c28", """PageRank: given edges as list of (from, to) among node labels (strings), damping factor d and iterations n,
run the power iteration: PR initialized uniformly; each step, rank flows along each out-edge equally; dangling nodes
distribute their rank uniformly to all nodes; newrank = (1-d)/N + d * (flow). Return the dict {node: rank} after n
iterations, ranks as floats. Node set = all nodes appearing in edges.""",
"""
def solve(edges, d, n):
    nodes = set()
    for a, b in edges:
        nodes.add(a); nodes.add(b)
    N = len(nodes)
    out = {u: [] for u in nodes}
    for a, b in edges:
        out[a].append(b)
    rank = {u: 1.0 / N for u in nodes}
    for _ in range(n):
        new = {u: (1 - d) / N for u in nodes}
        for u in nodes:
            if out[u]:
                share = rank[u] / len(out[u])
                for v in out[u]:
                    new[v] += d * share
            else:
                share = rank[u] / N
                for v in nodes:
                    new[v] += d * share
        rank = new
    return rank
""",
[([('a','b'),('b','a'),('a','c'),('c','a')], 0.85, 10), ([('a','b')], 0.85, 5)])

T("c29", """Minimum window substring: given string s and pattern t, return the smallest substring of s (by length;
ties: leftmost) containing all characters of t with multiplicity. Return '' if none exists.""",
"""
def solve(s, t):
    from collections import Counter
    need = Counter(t)
    missing = len(t)
    best = (None, 0, 0)
    i = 0
    for j, ch in enumerate(s):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        if missing == 0:
            while need[s[i]] < 0:
                need[s[i]] += 1
                i += 1
            if best[0] is None or j - i + 1 < best[2] - best[1] + 1:
                best = (s[i:j+1], i, j + 1)
            need[s[i]] += 1
            missing += 1
            i += 1
    return best[0] or ''
""",
[("ADOBECODEBANC","ABC",), ("a","aa",), ("aa","aa",)])

T("c30", """Bitmask TSP: given an n x n distance matrix (n <= 10) of ints, return the length of the shortest closed
tour visiting every city exactly once and returning to the start (city 0). Distances are symmetric.""",
"""
def solve(mat):
    n = len(mat)
    import functools
    FULL = (1 << n) - 1
    import collections
    dp = {}
    dp[(1, 0)] = 0
    for mask in range(1, FULL + 1):
        if not (mask & 1):
            continue
        for last in range(n):
            if not (mask >> last) & 1:
                continue
            cur = dp.get((mask, last))
            if cur is None:
                continue
            for nxt in range(n):
                if (mask >> nxt) & 1:
                    continue
                nm = mask | (1 << nxt)
                nc = cur + mat[last][nxt]
                key = (nm, nxt)
                if key not in dp or nc < dp[key]:
                    dp[key] = nc
    best = min(dp[(FULL, last)][0] if False else dp[(FULL, last)] + mat[last][0]
               for last in range(n) if (FULL, last) in dp)
    return best
""",
[([[0,10,15,20],[10,0,35,25],[15,35,0,30],[20,25,30,0]],),
 ([[0,1,2],[1,0,1],[2,1,0]],)])

T("c31", """Implement a class `Frac` for exact rational arithmetic: __init__(self, num, den) normalizes with
den>0 and gcd reduction; support +, *, == (with other Frac), and a method `text()` returning 'p/q' or 'p' when q==1.
solve() returns the class itself.""",
"""
def solve():
    from math import gcd
    class Frac:
        def __init__(self, num, den=1):
            if den == 0:
                raise ValueError
            g = gcd(abs(num), abs(den))
            num //= g; den //= g
            if den < 0:
                num, den = -num, -den
            self.num = num; self.den = den
        def __add__(self, other):
            return Frac(self.num * other.den + other.num * self.den, self.den * other.den)
        def __mul__(self, other):
            return Frac(self.num * other.num, self.den * other.den)
        def __eq__(self, other):
            return self.num == other.num and self.den == other.den
        def text(self):
            if self.den == 1:
                return str(self.num)
            return f"{self.num}/{self.den}"
